/**
 * Distinct authors of comments that are still live on this issue. Deleted
 * comments do not contribute an author. Order is unspecified.
 */
export async function listCommentAuthorIds(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  const rows = getDb()
    .selectDistinct({ authorId: comments.authorId })
    .from(comments)
    .where(
      and(
        ...compact(
          orgPredicate(comments.orgId, orgId),
          eq(comments.issueId, issueId),
          shouldFilterArchived({}) ? isNull(comments.archivedAt) : undefined,
        ),
      ),
    )
    .all();

  return rows.map((row) => brandId<UserId>(row.authorId));
}

