/**
 * People shown on an issue's participants strip: the issue author, the current
 * assignee, and authors of comments that have not been deleted. Each id is
 * returned once, and only while that person is an active member of the org.
 */
export async function getIssueParticipants(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly UserId[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "comment:read", issueResource(issue));

  const commentAuthorIds = await commentRepo.listCommentAuthorIds(orgId, issueId);
  const candidateIds = new Set<UserId>([issue.authorId, ...commentAuthorIds]);
  if (issue.assigneeId !== null) candidateIds.add(issue.assigneeId);

  const participants: UserId[] = [];
  for (const userId of candidateIds) {
    const member = await memberRepo.findMember(orgId, userId);
    if (member && member.status === "active") participants.push(userId);
  }
  return participants;
}","tool_output_for_prompt":"The file /private/tmp/bench-scratch/6a967dda-5c7f-4895-b532-64d97499c6a0/src/server/services/comment-service.ts has been updated successfully.","tool_output_for_prompt_concise":"The file /private/tmp/bench-scratch/6a967dda-5c7f-4895-b532-64d97499c6a0/src/server/services/comment-service.ts has been updated.","absolute_path":"/private/tmp/bench-scratch/6a967dda-5c7f-4895-b532-64d97499c6a0/src/server/services/comment-service.ts","edits":{"details":[{"old_string":"  return commentRepo.listThread(orgId, issueId);
